CREATE COLUMN TABLE "TEST_AP"."IPF2" ("DocEntry" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT, "AlcCode" NVARCHAR(2) NOT NULL , "OhType" NVARCHAR(1), "CostSum" DECIMAL(21,6) CS_FIXED, "CostSumFC" DECIMAL(21,6) CS_FIXED, "Factor" DECIMAL(21,6) CS_FIXED, "CostType" NVARCHAR(1) DEFAULT 'F' NOT NULL , "Locked" NVARCHAR(1) DEFAULT 'N', "LaCAllcAcc" NVARCHAR(15), "CostSumSC" DECIMAL(21,6) CS_FIXED, "InCustCalc" NVARCHAR(1) DEFAULT 'N', "OpenCost" DECIMAL(21,6) CS_FIXED, "OpenCostFC" DECIMAL(21,6) CS_FIXED, "OpenCostSC" DECIMAL(21,6) CS_FIXED, "AgentCode" NVARCHAR(15), "AgentName" NVARCHAR(100), "CostCateg" NVARCHAR(1), "EncryptIV" NVARCHAR(100), PRIMARY KEY ("DocEntry", "AlcCode", "CostType")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."IPF2" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$DocEntry$LineNum$','DocEntry','LineNum'));
